import{_ as d,C as a,o,c as r,E as i,a2 as l}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.8","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.8","type":"implementation-case","domain":"TMPA","version":"I0.8","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.8.md","filePath":"zh/publications/implementation-case-i0.8.md","lastUpdated":1786339128000}'),n={name:"zh/publications/implementation-case-i0.8.md"};function s(c,t,p,h,u,g){const e=a("ArticleCover");return o(),r("div",null,[i(e,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"CodeFlowMu V1.6.0 针对 TMPA Core S0.6 精确输入的产品运行与自包含公开复现器。",version:"I0.8",status:"S0.6 产品证据草稿 · 14/14 PASS",languageHref:"/en/publications/implementation-case-i0.8",languageLabel:"English"}),t[0]||(t[0]=l(`<p>status=&quot;S0.6 产品证据草稿 · 14/14 PASS&quot; languageHref=&quot;/en/publications/implementation-case-i0.8&quot; languageLabel=&quot;English&quot; /&gt;</p><h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="tmpa-core-s0-6、fcop、codeflowmu-v1-6-0-与保留的现场证据" tabindex="-1">TMPA Core S0.6、FCoP、CodeFlowMu V1.6.0 与保留的现场证据 <a class="header-anchor" href="#tmpa-core-s0-6、fcop、codeflowmu-v1-6-0-与保留的现场证据" aria-label="Permalink to &quot;TMPA Core S0.6、FCoP、CodeFlowMu V1.6.0 与保留的现场证据&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> 草稿 I0.8<br><strong>状态：</strong> 作者制作的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.6">TMPA Core Specification S0.6</a>，Commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code><br><strong>受测产品：</strong> CodeFlowMu V1.6.0，实现 Commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code><br><strong>证据采集：</strong> 2026-08-10，Asia/Shanghai<br><strong>正式证据包：</strong> <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</code><br><strong>压缩包 SHA-256：</strong> <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code><br><strong>权威边界：</strong> 本报告属于证据性、非规范性文档；只有 Core Specification 定义 TMPA 要求。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.8 使用规范仓库 Commit 固定的原始 LF 字节，对 CodeFlowMu V1.6.0 执行 TMPA Core S0.6 全部十四项强制准则。产品级结果为 <strong>14 PASS、0 PARTIAL、0 NOT RUN、0 FAIL</strong>。CodeFlowMu 产品 Runner 调用自身同步 <code>GovernanceReader</code>，不调用 TMPA Reference Reader。输入 Bundle Digest 为 <code>sha256:251914ee55922d20c9bd23943a4ff445bccaa5835e1fcc11b8562f3f384243fa</code>。</p><p>本次工程升级关闭了相对于 I0.7/S0.5 基线的 S0.6 可观察差异：字节相同的观测保留每个贡献来源 ID；高风险批准必须同时满足允许的裁决对象类型、有效角色 Assignment、允许角色、批准决定，以及 Profile 要求时相互独立的行为者；所有规范排序采用不依赖 Locale 的 Unicode 码点顺序，并包含 U+E000 与 U+10000 回归。CodeFlowMu 内置 TMPA 套件为 23/23，Runtime 为 1,485 passed / 0 failed / 1 skipped，Shell 为 777/777，锁定的 FCoP 参考实现为 1,210 passed / 2 skipped。</p><p>证据包包含自包含公开复现器。干净环境执行 <code>npm ci</code> 与 <code>npm test</code>，先核验七份正式 S0.6 文件的字节摘要，再运行 CodeFlowMu 产品 Reader，得到 14/14 PASS；复现该符合性切片不需要私有 CodeFlowMu 母体仓库。当前最强且不越界的结论仍是：<strong>固定 Bundle 下由作者运行所 demonstrated 的行为</strong>。它不是独立认证、独立采用、任意输入上的证明，也不证明 AI 幻觉已经消除。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>I0.8 回答：</p><ol><li>CodeFlowMu V1.6.0 产品 Reader 是否针对同一个精确、固定的输入 Bundle 满足 S0.6 C01–C14？</li><li>来源保留、完整人工批准授权和不依赖 Locale 的排序这三项 S0.6 可观察变化，是否已实现且没有破坏 I0.7 demonstrated 的 S0.5 行为？</li><li>在无法访问私有 CodeFlowMu 母体仓库时，符合性切片能否公开复跑？</li><li>哪些证据仍是作者本地运行，哪些结论仍未获得支持？</li></ol><p>裁决单位是固定 Bundle 上绑定具体准则的主张。四个证据层级严格分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.8 中的含义</th><th style="text-align:right;">是否达到</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.6 规范定义</td><td style="text-align:right;">是</td></tr><tr><td>Implemented</td><td>CodeFlowMu 中存在相应机制</td><td style="text-align:right;">是</td></tr><tr><td>Demonstrated</td><td>执行产生了可检查证据</td><td style="text-align:right;">是，仅限固定 C01–C14 Bundle</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td><td style="text-align:right;">否</td></tr></tbody></table><h1 id="_2-架构与证据边界" tabindex="-1">2. 架构与证据边界 <a class="header-anchor" href="#_2-架构与证据边界" aria-label="Permalink to &quot;2. 架构与证据边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ 理论指导工程方向</span></span>
<span class="line"><span>TMPA Core S0.6</span></span>
<span class="line"><span>        ↓ 固定规范对象、Reader 与符合性契约</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 提供现实协作与证据协议</span></span>
<span class="line"><span>CodeFlowMu V1.6.0 应用执行与消费层</span></span>
<span class="line"><span>        ↓ 产品 Reader、Runtime、角色、恢复与审计</span></span>
<span class="line"><span>WP-13 与其他有限案例</span></span></code></pre></div><p>TMPA 理论指导 CodeFlowMu 的工程方向，Core S0.6 固定本报告接受评估的规范行为。FCoP 是 CodeFlowMu 使用的现实协作与证据协议，不是应用程序；<code>fcop</code> 与 <code>fcop-mcp</code> 是参考实现，不等于协议本身。按照 CodeFlowMu 工程架构 [7]，CodeFlowMu 是应用执行与消费层：负责产生协作事实、运行 Adapter 与 Reader、投影治理图，并让恢复与治理门禁消费重建结果。WP-13 保留为有界的证据准入案例；小典 AI 仅作为作者报告的工程谱系，不纳入评估证据；二者都不能替代 S0.6 产品运行。</p><p>概念依赖与历史形成过程保持分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前指导：TMPA 理论 → Core 要求 → FCoP 协议</span></span>
<span class="line"><span>                                  → CodeFlowMu 工程落实</span></span>
<span class="line"><span>历史反馈：小典实践 → 早期 TMPA → FCoP 提取</span></span>
<span class="line"><span>                               → CodeFlowMu 工程实现</span></span>
<span class="line"><span>FCoP + CodeFlowMu 结果 → 当前 TMPA 形式化</span></span></code></pre></div><p>历史反馈解释理论如何成熟，但不会倒置当前权威关系。产品行为可以提供证据或推动后续修订，却不能重定义当前 Core。</p><h1 id="_3-锁定来源与证据设计" tabindex="-1">3. 锁定来源与证据设计 <a class="header-anchor" href="#_3-锁定来源与证据设计" aria-label="Permalink to &quot;3. 锁定来源与证据设计&quot;">​</a></h1><table tabindex="0"><thead><tr><th>来源</th><th>锁定标识</th><th>I0.8 中的作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.6，Commit <code>8989657…</code></td><td>C01–C14 规范目标</td><td>规范，不是产品证据</td></tr><tr><td>CodeFlowMu</td><td>V1.6.0，Commit <code>62440a5…</code></td><td>受测产品实现</td><td>本地实现 Commit，不表述为公开 Release</td></tr><tr><td>公开复现器</td><td>29 个锁定文件</td><td>公开复跑符合性切片</td><td>不公开或复现整个私有产品</td></tr><tr><td>FCoP 参考实现</td><td>Commit <code>da79dfe…</code></td><td>锁定依赖基线</td><td>测试结果不是抽象协议证明</td></tr><tr><td>I0.7</td><td>S0.5 / CodeFlowMu V1.4.1</td><td>历史回归基线</td><td>保留精确的旧版含义</td></tr><tr><td>WP-13 V3</td><td>已出版证据包</td><td>证据门禁现场案例</td><td>未复跑，也未提升为符合性证明</td></tr></tbody></table><p>七份正式 S0.6 输入——四份 Schema、规范化 Profile、生命周期 Profile 与 Fixture——均与 GitHub 字节完全一致。第一次提交的压缩包包含 Windows Checkout 转换后的 CRLF 副本，出版预检拒绝了该包。最终包使用 Git 原始 Blob 字节重新运行产品准则，并重新生成全部关联 Digest，而不是修改旧结果 JSON。</p><h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>主要产品运行与全量套件均由作者在固定输入上执行。跳过项保持为跳过项。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>S0.6 产品 C01–C14</td><td style="text-align:right;">14 PASS / 0 FAIL / 0 PARTIAL / 0 NOT RUN</td><td style="text-align:right;">0</td><td>直接执行 CodeFlowMu 产品 Reader</td></tr><tr><td>CodeFlowMu 内置 TMPA</td><td style="text-align:right;">23/23</td><td style="text-align:right;">0</td><td>包含显式 S0.5 兼容与 S0.6 回归</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">5 个有效 + 3 个预期无效 Fixture</td><td style="text-align:right;">0</td><td>产品协议测试，与 TMPA 裁决分开</td></tr><tr><td>Protocol / Runtime / Shell Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,485 passed、0 failed、1 skipped</td><td style="text-align:right;">0</td><td>作者本地完整 Runtime 运行</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">777 passed、0 failed</td><td style="text-align:right;">0</td><td>作者本地完整 Shell 运行</td></tr><tr><td>FCoP 锁定参考基线</td><td style="text-align:right;">1,210 passed、2 skipped</td><td style="text-align:right;">0</td><td>参考实现，不是协议证明</td></tr><tr><td>公开复现器</td><td style="text-align:right;"><code>npm ci</code> + 产品 14/14 PASS</td><td style="text-align:right;">0</td><td>自包含符合性切片复跑</td></tr></tbody></table><p>最终 Conformance Result 通过 S0.6 结果 Schema，记录 <code>product_reader_called: true</code>、<code>reference_reader_called: false</code>、实现 <code>codeflowmu/V1.6.0</code>，证据层级为 <code>demonstrated</code>。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.6 准则</th><th style="text-align:right;">裁决</th><th>执行观察</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td style="text-align:right;"><strong>PASS</strong></td><td>四份正式 S0.6 Schema 全部编译；错误结构与声明 <code>date-time</code> 的负向案例被确定性拒绝。</td></tr><tr><td>C02</td><td>主载体与不可变性</td><td style="text-align:right;"><strong>PASS</strong></td><td>内容寻址修订保持可归责；主载体冲突不能取得权威；更正仍是独立证据。</td></tr><tr><td>C03</td><td>重复身份与来源</td><td style="text-align:right;"><strong>PASS</strong></td><td>同 ID 异内容被隔离；字节相同的观测投影为一个节点，同时保留全部确定排序的 <code>source_id</code>。</td></tr><tr><td>C04</td><td>串行连续性与异步推进</td><td style="text-align:right;"><strong>PASS</strong></td><td>流缺口与重号持续可见；无关流可以推进；到达顺序不改变输出。</td></tr><tr><td>C05</td><td>角色权威</td><td style="text-align:right;"><strong>PASS</strong></td><td>权限拒绝与权限不确定分支保持分离，且不能修改重建状态。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td style="text-align:right;"><strong>PASS</strong></td><td>非法迁移被拒绝；缺少独立验收时完成保持不确定且不能推进。</td></tr><tr><td>C07</td><td>职责分离与人工批准</td><td style="text-align:right;"><strong>PASS</strong></td><td>错误批准类型、缺少 Assignment、不允许角色、缺少批准决定和自我批准均保持 <code>pending_human</code>；有效的已分配独立批准可以清除门禁。</td></tr><tr><td>C08</td><td>完整性篡改</td><td style="text-align:right;"><strong>PASS</strong></td><td>被覆盖内容篡改产生 <code>INTEGRITY_MISMATCH</code>，对象退出权威节点，失败来源仍被保留。</td></tr><tr><td>C09</td><td>缺失引用</td><td style="text-align:right;"><strong>PASS</strong></td><td>缺失依赖与主张证据保持可见并传播不确定结果，不虚构事实。</td></tr><tr><td>C10</td><td>禁止引用环</td><td style="text-align:right;"><strong>PASS</strong></td><td>只隔离受影响的禁止环子图，无关有效节点仍可使用。</td></tr><tr><td>C11</td><td>确定性重建</td><td style="text-align:right;"><strong>PASS</strong></td><td>固定来源排列产生字节等价结果；规范顺序采用 Unicode 码点顺序，包括 U+E000 在 U+10000 之前。</td></tr><tr><td>C12</td><td>冲突保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>矛盾复核保持 disputed，直到授权解决者行动；未授权裁决保留为证据但不能清除冲突。</td></tr><tr><td>C13</td><td>恢复</td><td style="text-align:right;"><strong>PASS</strong></td><td>全新 Reader 能一致重建生命周期、责任、依赖、失败、恢复动作与父子状态。</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>只有已验收授权链进入 archive，之前的任务、报告、复核和迁移历史仍可重建。</td></tr></tbody></table><h1 id="_6-s0-5-→-s0-6-产品差异" tabindex="-1">6. S0.5 → S0.6 产品差异 <a class="header-anchor" href="#_6-s0-5-→-s0-6-产品差异" aria-label="Permalink to &quot;6. S0.5 → S0.6 产品差异&quot;">​</a></h1><h2 id="_6-1-c03——聚合不丢失来源" tabindex="-1">6.1 C03——聚合不丢失来源 <a class="header-anchor" href="#_6-1-c03——聚合不丢失来源" aria-label="Permalink to &quot;6.1 C03——聚合不丢失来源&quot;">​</a></h2><p>I0.7 已演示同 ID 异内容候选的冲突处理。S0.6 增加第二条边界：多个字节相同的观测不能生成重复节点，但聚合也不能抹除观测来源。V1.6.0 输出一个规范节点和完整、按码点排序的 <code>source_ids</code> 列表。</p><h2 id="_6-2-c07——批准是授权治理对象" tabindex="-1">6.2 C07——批准是授权治理对象 <a class="header-anchor" href="#_6-2-c07——批准是授权治理对象" aria-label="Permalink to &quot;6.2 C07——批准是授权治理对象&quot;">​</a></h2><p>S0.5 基线已演示角色分离与高风险人工门禁。S0.6 让授权合同可以直接测试：只有对象类型被允许、行为者具有匹配 Assignment、角色被允许、正文包含批准决定，并且 Profile 要求时行为者相互独立，批准才成立。四个负向分支继续等待，不会被当作隐式批准。</p><h2 id="_6-3-c11——确定性意味着不依赖-locale" tabindex="-1">6.3 C11——确定性意味着不依赖 Locale <a class="header-anchor" href="#_6-3-c11——确定性意味着不依赖-locale" aria-label="Permalink to &quot;6.3 C11——确定性意味着不依赖 Locale&quot;">​</a></h2><p>S0.6 消除规范排序中的环境歧义。V1.6.0 在对象 Key、来源、图遍历、问题与输出集合中统一采用 Unicode 码点顺序。U+E000/U+10000 Fixture 可以识别普通 ASCII 测试无法发现的 UTF-16 Code Unit 排序错误。</p><h2 id="_6-4-兼容边界" tabindex="-1">6.4 兼容边界 <a class="header-anchor" href="#_6-4-兼容边界" aria-label="Permalink to &quot;6.4 兼容边界&quot;">​</a></h2><p>CodeFlowMu 内置套件包含显式 S0.5/I0.7 兼容路径。I0.7 继续作为精确的 S0.5 历史产品结果；I0.8 不改写其输入、准则、产品版本或证据包。</p><h1 id="_7-公开复现器" tabindex="-1">7. 公开复现器 <a class="header-anchor" href="#_7-公开复现器" aria-label="Permalink to &quot;7. 公开复现器&quot;">​</a></h1><p>正式压缩包包含 29 文件的自包含复现器，其中包括 Package Lock、产品 Reader、Protocol Validator、Profile、Fixtures、Runner 与正式输入。要求 Node.js 22 或更新版本以及公共 npm Registry：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd public-reproducer</span></span>
<span class="line"><span>npm ci</span></span>
<span class="line"><span>npm test</span></span></code></pre></div><p>测试首先核验七个上游 SHA-256，然后调用打包的 CodeFlowMu <code>GovernanceReader</code>。记录的干净副本运行和出版预检均得到 14 PASS / 0 FAIL。该复现器让符合性切片可以公开检查，但不表示私有母体仓库或完整应用已经公开。</p><h1 id="_8-保留的-wp-13-证据门禁案例" tabindex="-1">8. 保留的 WP-13 证据门禁案例 <a class="header-anchor" href="#_8-保留的-wp-13-证据门禁案例" aria-label="Permalink to &quot;8. 保留的 WP-13 证据门禁案例&quot;">​</a></h1><p>WP-13 对工程解释仍有价值，但 I0.8 没有重新执行它。该案例记录了角色分离工作流：带完成含义的声明被暂停，直到持久证据、正式报告与 QA 验证建立。后续 Gate C 裁决接受交付，而 Active、Push/发布与 Archive 仍是独立决定。</p><p>该案例支持证据门禁、分阶段权威与同任务恢复，不证明幻觉消除、普遍错误声明检测或 S0.6 符合性。C01–C14 结果来自 V1.6.0 产品 Bundle，不来自 WP-13。</p><h1 id="_9-三值治理解释" tabindex="-1">9. 三值治理解释 <a class="header-anchor" href="#_9-三值治理解释" aria-label="Permalink to &quot;9. 三值治理解释&quot;">​</a></h1><p>TMPA 将语义判断与视图分类分开：</p><table tabindex="0"><thead><tr><th>判断</th><th>典型视图</th><th>含义</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>所需证据与适用规则能够建立结论。</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>确定性违规排除受影响的证据或动作。</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>证据缺失、冲突，或仍需授权人工裁决。</td></tr></tbody></table><p>I0.8 让这种分离可观察。错误类型或自我签发的批准被保留，但不能满足 C07。C09 的缺失引用让依赖主张保持不确定，而不是变成错误或完成。C12 的未授权解决对象仍是证据，但作为解决动作无效。C08 的完整性失败隔离覆盖内容，同时保留来源记录。</p><h1 id="_10-证据完整性与出版预检" tabindex="-1">10. 证据完整性与出版预检 <a class="header-anchor" href="#_10-证据完整性与出版预检" aria-label="Permalink to &quot;10. 证据完整性与出版预检&quot;">​</a></h1><p>正式压缩包包含 195 个文件，其中 194 个 Payload 文件进入内部 SHA-256 Manifest。外部 SHA-256 为 <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>。独立出版预检确认：</p><ul><li>ZIP 结构完整，文件名全部 ASCII；</li><li>每个文件严格 UTF-8 解码通过；</li><li>137 个 JSON 文件和 11 条 JSONL 记录通过解析；</li><li>内部 SHA-256 为 194/194；</li><li>七份正式 S0.6 输入全部字节相同；</li><li>C01–C14 结果 Envelope 通过 Schema；</li><li>产品 Reader 被调用，没有用 Reference Reader 替代；</li><li>自包含复现器得到 14/14 PASS。</li></ul><p>最初的 2026-08-09 候选包不进入出版。它包含语义相同但被 Checkout 转换为 CRLF 的正式输入副本、错误的 Manifest 条目计数声明，并且没有自包含公开复跑路径。修正后的 2026-08-10 压缩包是唯一 I0.8 正式主包。</p><h1 id="_11-限制" tabindex="-1">11. 限制 <a class="header-anchor" href="#_11-限制" aria-label="Permalink to &quot;11. 限制&quot;">​</a></h1><ol><li>产品与全量套件证据由作者运行；没有独立组织认证或采用该实现。</li><li>CodeFlowMu 实现 Commit 位于本地，不表述为公开 Release、Tag 或完整公开源码树。</li><li>公开复现器暴露符合性切片，不包含完整私有 CodeFlowMu 应用及其全部 Runtime/Shell 环境。</li><li>Runtime 保留 1 项 skipped；FCoP 参考实现在迁移布局下保留 2 项历史样例 skipped。</li><li>C11 评估固定 Fixture 与已声明排列，不是任意图或敌对平台上的形式证明。</li><li>C08 演示治理对象完整性处理，不代表模型真实性、身份认证、安装器保护或拜占庭韧性。</li><li>全量性能、代表性 SME 成本、比较基线与独立部署仍是开放的经验问题。</li><li>WP-13 是有限治理案例，不是幻觉消除基准。</li></ol><h1 id="_12-主张台账" tabindex="-1">12. 主张台账 <a class="header-anchor" href="#_12-主张台账" aria-label="Permalink to &quot;12. 主张台账&quot;">​</a></h1><table tabindex="0"><thead><tr><th>主张</th><th>I0.8 处理</th></tr></thead><tbody><tr><td>TMPA Core S0.6 定义 C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.6.0 包含相应产品机制</td><td><strong>Implemented</strong></td></tr><tr><td>固定产品 Bundle 记录 14/14 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>自包含符合性切片可以公开复跑</td><td><strong>Demonstrated</strong></td></tr><tr><td>完整私有 CodeFlowMu 应用可以公开复现</td><td><strong>未主张</strong></td></tr><tr><td>结果已独立认证或采用</td><td><strong>未演示</strong></td></tr><tr><td>WP-13 证明消除幻觉</td><td><strong>禁止结论</strong></td></tr></tbody></table><h1 id="_13-工程结论" tabindex="-1">13. 工程结论 <a class="header-anchor" href="#_13-工程结论" aria-label="Permalink to &quot;13. 工程结论&quot;">​</a></h1><p>I0.8 将 Implementation Case 从精确的 S0.5 产品结果推进到精确输入的 S0.6 产品结果。CodeFlowMu V1.6.0 通过全部十四项强制准则，并直接暴露 S0.6 在来源保留、批准权威和不依赖 Locale 的确定性重建方面的变化。自包含复现器缩小了作者本地产品证据与公开检查之间的差距，同时没有把私有完整应用包装成开源或独立验证。</p><p>该结果强化 TMPA 可实现性的工程证据，而不是证明理论逻辑为真。TMPA 理论指导系统设计，Core S0.6 固定受评估要求，FCoP 提供现实协作与证据协议，CodeFlowMu 是受测的应用执行与消费层，WP-13 是有限现场案例。独立采用与更广泛经验评估仍属于后续工作。</p><h1 id="证据获取" tabindex="-1">证据获取 <a class="header-anchor" href="#证据获取" aria-label="Permalink to &quot;证据获取&quot;">​</a></h1><p>I0.8 正式证据包为 <a href="/joinwell52/evidence/tmpa/i0.8/tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip">tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</a>。同目录文件 <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip.sha256</code> 记录 <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code>。</p><p>I0.7 及其 V1.4.1/S0.5 压缩包继续保留在版本路径。被拒绝的 I0.8 候选包不属于公开出版集合。Git History 是出版版本历史，不存在具有编辑权威的并行论文数据库。</p><h1 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.6,” Commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code>. GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.9.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” 参考实现 Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.6.0 S0.6 Product Conformance,” 实现 Commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code>, 2026.</p><p>[5] TMPA Project. “I0.8 CodeFlowMu V1.6.0 S0.6 Evidence,” Package <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810</code>, 2026.</p><p>[6] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” 2026.</p><p>[7] CodeFlowMu Project. “CodeFlowMu V1.4–V1.5 TMPA × FCoP × 应用统一架构”，<code>docs/TMPA-GOVERNANCE.md</code>。GitHub，2026。<code>https://github.com/joinwell52-AI/codeflowmu/blob/main/docs/TMPA-GOVERNANCE.md</code>。</p>`,70))])}const P=d(n,[["render",s]]);export{m as __pageData,P as default};
